#import <WebKit/WebKit.h>
static NSUInteger checks;
static void Check(BOOL value,NSString *message){checks++;if(!value){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
static void Wait(BOOL(^ready)(void)){NSDate *limit=[NSDate dateWithTimeIntervalSinceNow:15];while(!ready() && limit.timeIntervalSinceNow>0)[NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.01]];Check(ready(),@"renderer callback completes");}
static NSDictionary *Inspect(NSString *text){NSDictionary *snapshot=@{@"paths":@[@"sample.md"],@"files":@{@"sample.md":@{@"text":text,@"version":AMPreflightHash([text dataUsingEncoding:NSUTF8StringEncoding])}},@"version":@"synthetic"};NSDictionary *report=AMPreflightCheck(snapshot,@"Synthetic requirements",NSMutableDictionary.dictionary,nil);Check([report[@"coverage"] count]>=3 && [report[@"coverage"][1][@"status"] hasPrefix:@"已渲染"],@"actual offline math rendering completes, not just syntax inspection");return report;}
static BOOL Has(NSDictionary *report,NSString *needle){for(NSDictionary *row in report[@"issues"])if([row[@"message"] containsString:needle])return YES;return NO;}
static NSData *Image(NSUInteger width,NSUInteger height){NSBitmapImageRep *bitmap=[[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:width pixelsHigh:height bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:0 bitsPerPixel:0];memset(bitmap.bitmapData,160,bitmap.bytesPerRow*height);return [bitmap representationUsingType:NSBitmapImageFileTypePNG properties:@{}];}
static id JS(WKWebView *web,NSString *script){__block id answer=nil;__block BOOL finished=NO;[web evaluateJavaScript:script completionHandler:^(id value,NSError *error){Check(!error,@"preview script inspection succeeds");answer=value;finished=YES;}];Wait(^BOOL{return finished;});return answer;}
int main(){@autoreleasepool{
 [NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyProhibited];AMInstallRenderer();
 NSString *valid=@"# Valid math\n\n$\\mathbb{R}\\oplus\\mathfrak{g}$、$L=I\\omega$、$\\mathbf{L}$ 的大小不变。\n\n$`\\frac{1}{2}x^2`$\n\n$$\\begin{aligned}x&=1\\\\y&=2\\end{aligned}$$\n\n```math\n\\sqrt{x+1}\n```\n\nCosts $100 and $200. `\\badcommand $x$`\n\n```python\ntext = '$\\badcommand$'\n```\n\n<img src=\"missing.png\" alt=\"$x$\">\n";
 NSDictionary *report=Inspect(valid);Check([report[@"coverage"][1][@"status"] containsString:@"6 个公式"],@"adjacent formulae all render even when preceding formula has TeX commands");Check(!Has(report,@"公式渲染未完成") && !Has(report,@"未闭合") && !Has(report,@"裸露"),@"complex legal formula, currency, inline code, fences and HTML attributes avoid false format errors");
 Check(Has(Inspect(@"$\\frac{1}{2$\n"),@"公式渲染未完成"),@"actual MathJax catches missing brace");
 Check(Has(Inspect(@"$\\unsupportedcommand{x}$\n"),@"公式渲染未完成"),@"unknown command classified as compatibility warning");
 Check(Has(Inspect(@"$$\nx+1\n"),@"块公式未闭合"),@"unclosed block formula detected");
 Check(Has(Inspect(@"$x+1\n"),@"未闭合"),@"plain algebra with a missing delimiter is not silently skipped");
 Check(!Has(Inspect(@"Files: ./assets/$x+1.md and C:\\frac\\data.\nCosts $100 and $200.\n"),@"未闭合"),@"paths and currency do not become incomplete formula warnings");
 Check(Has(Inspect(@"$\\mathbf{x}\n"),@"未闭合"),@"unclosed inline formula detected");
 Check(Has(Inspect(@"A literal \\mathbf{x} outside math.\n"),@"裸露"),@"escaped or missing math delimiter leaves visible compatibility warning");
 AMDocumentView *view=[[AMDocumentView alloc] initWithFrame:NSMakeRect(0,0,700,480)];NSWindow *host=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,700,480) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];host.releasedWhenClosed=NO;host.contentView=view;
 NSString *attack=@"# Preview\n<script>window.materialExecuted=1</script><img src=\"https://example.invalid/x\" onerror=\"window.materialExecuted=1\"><a href=\"file:///private/etc/passwd\">link</a>\n\n$x^2$\n";
 [view loadSnapshot:@{@"files":@{@"test.md":@{@"text":attack}}} path:@"test.md"];WKWebView *web=[view valueForKey:@"web"];__block BOOL ready=NO;
 Wait(^BOOL{if(!ready){[web evaluateJavaScript:@"!!document.querySelector('mjx-container')" completionHandler:^(id result,NSError *error){ready=[result boolValue];}];}return ready;});
 __block NSDictionary *state=nil;[web evaluateJavaScript:@"({executed:!!window.materialExecuted,external:!!document.querySelector('#content img[src^=https]'),link:!!document.querySelector('#content a[href]'),formula:!!document.querySelector('mjx-container')})" completionHandler:^(id result,NSError *error){state=result;}];Wait(^BOOL{return state!=nil;});Check(![state[@"executed"] boolValue] && ![state[@"external"] boolValue] && ![state[@"link"] boolValue] && [state[@"formula"] boolValue],@"material scripts, event handlers, remote images and file links cannot execute or navigate");
 NSDictionary *math=JS(web,@"({svg:document.querySelectorAll('mjx-container svg').length,assistive:[...document.querySelectorAll('mjx-assistive-mml')].map(n=>({clip:getComputedStyle(n).clip,display:getComputedStyle(n).display}))})");
 Check([math[@"svg"] integerValue]==1,@"one visible SVG is emitted per formula");for(NSDictionary *node in math[@"assistive"])Check(![node[@"clip"] isEqual:@"auto"] && ![node[@"display"] isEqual:@"none"],@"screen-reader MathML is visually clipped while remaining accessible");
 [view locateLine:0];[view showSource:YES];Check(![[view valueForKey:@"sourceScroll"] isHidden],@"source toggle and zero-line navigation are safe");
 __block BOOL dark=NO;host.appearance=[NSAppearance appearanceNamed:NSAppearanceNameDarkAqua];[web evaluateJavaScript:@"document.documentElement.dataset.appearance" completionHandler:^(id result,NSError *error){dark=[result isEqual:@"dark"];}];Wait(^BOOL{return dark;});Check([[[view valueForKey:@"sourceText"] string] isEqual:attack],@"theme updates web and source without rebuilding or losing text");
 NSData *first=Image(12,20),*second=Image(30,40);NSDictionary *pictures=@{@"files":@{@"one.png":@{@"data":first,@"image":@YES,@"version":AMPreflightHash(first)},@"two.png":@{@"data":second,@"image":@YES,@"version":AMPreflightHash(second)}}};
 [view loadSnapshot:pictures path:@"one.png"];Wait(^BOOL{return [JS(web,@"document.querySelector('#content img')?.naturalWidth||0") integerValue]==12;});NSString *firstSource=JS(web,@"document.querySelector('#content img').src");
 [view loadSnapshot:pictures path:@"two.png"];[view setAnnotations:@[@{@"id":@"two-error",@"region":@[@.1,@.2,@.3,@.4],@"markdown":@"## 计算有误\n\n应为 $x^2$。<script>window.materialExecuted=1</script>"}] selected:@"two-error"];
 Wait(^BOOL{return [JS(web,@"document.querySelector('#content img')?.naturalWidth||0") integerValue]==30;});Check(![firstSource isEqual:JS(web,@"document.querySelector('#content img').src")],@"different image bytes use different URLs and never reuse the previous image cache");
 NSDictionary *annotation=JS(web,@"(()=>{const button=document.querySelector('.am-note-trigger');button.dispatchEvent(new FocusEvent('focus'));return {boxes:document.querySelectorAll('.am-annotation-box').length,open:!document.querySelector('.am-note-body').hidden,color:getComputedStyle(document.querySelector('.am-annotation-box')).borderTopColor,text:document.querySelector('.am-note-body').textContent,executed:!!window.materialExecuted};})()");

 Check([annotation[@"boxes"] integerValue]==1 && [annotation[@"open"] boolValue] && [annotation[@"color"] isEqual:@"rgb(215, 0, 21)"] && [annotation[@"text"] containsString:@"计算有误"] && ![annotation[@"executed"] boolValue],@"red image region opens one sanitized, keyboard-accessible explanation");
 JS(web,@"document.querySelector('.am-note-trigger').dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");Check([JS(web,@"document.querySelector('.am-note-body').hidden") boolValue],@"Escape dismisses the annotation");
 NSString *code=@"# Synthetic code\nprint('$x^2$')\nmessage = '<script>window.materialExecuted=1</script>'\n";[view loadSnapshot:@{@"files":@{@"answer.py":@{@"text":code}}} path:@"answer.py"];[view setAnnotations:@[@{@"id":@"code-line",@"line":@2,@"markdown":@"## 核对这一行"}] selected:@"code-line"];
 Wait(^BOOL{return [JS(web,@"!![...document.querySelectorAll('.am-plain pre[data-line]')].find(n=>n.dataset.line==='2')?.querySelector('.am-note-trigger')") boolValue];});
 NSDictionary *codeState=JS(web,@"(()=>{document.querySelector('.am-note-trigger').dispatchEvent(new MouseEvent('click'));return {plain:document.querySelector('.am-plain').textContent,open:!document.querySelector('.am-note-body').hidden,formulas:document.querySelectorAll('mjx-container').length,executed:!!window.materialExecuted};})()");Check([codeState[@"plain"] containsString:@"print('$x^2$')"] && [codeState[@"open"] boolValue] && ![codeState[@"formulas"] integerValue] && ![codeState[@"executed"] boolValue],@"code source remains literal and its line annotation is readable without a second preview");
 [view loadSnapshot:pictures path:@"two.png"];[view setAnnotations:@[@{@"id":@"selected-error",@"region":@[@.1,@.2,@.3,@.4],@"markdown":@"选中批注"},@{@"id":@"overlapping-error",@"region":@[@.1,@.2,@.3,@.4],@"markdown":@"其他批注"}] selected:@"selected-error"];
 Wait(^BOOL{return [JS(web,@"document.querySelectorAll('.am-note').length===2") boolValue];});
 Check([JS(web,@"(()=>{const selected=document.querySelector('.am-note[data-selected=true]'),button=selected.querySelector('button'),r=button.getBoundingClientRect(),hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);selected.dispatchEvent(new MouseEvent('mouseenter'));return hit?.closest('button')===button&&!selected.querySelector('aside').hidden;})()") boolValue],@"selected overlapping image annotation remains the pointer target and opens its own explanation");
 JS(web,@"(()=>{const marker=document.querySelector('.am-note[data-selected=true]');marker.dispatchEvent(new MouseEvent('mouseleave'));return true;})()");Check(![JS(web,@"document.querySelector('.am-note[data-selected=true] aside').hidden") boolValue],@"hover explanation remains open while crossing into its card");
 JS(web,@"document.querySelector('.am-note[data-selected=true]').dispatchEvent(new MouseEvent('mouseenter'))");NSDate *hoverDeadline=[NSDate dateWithTimeIntervalSinceNow:.35];while(hoverDeadline.timeIntervalSinceNow>0)[NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.01]];Check(![JS(web,@"document.querySelector('.am-note[data-selected=true] aside').hidden") boolValue],@"entering the explanation cancels pending close so long text can be read and scrolled");
 JS(web,@"document.querySelector('.am-note[data-selected=true]').dispatchEvent(new MouseEvent('mouseleave'))");Wait(^BOOL{return [JS(web,@"document.querySelector('.am-note[data-selected=true] aside').hidden") boolValue];});
 Check([JS(web,@"(()=>{const marker=document.querySelector('.am-note[data-selected=true]'),popup=marker.querySelector('aside');marker.dispatchEvent(new MouseEvent('mouseenter'));marker.dispatchEvent(new FocusEvent('focusout',{relatedTarget:popup}));return !popup.hidden&&popup.tabIndex===-1;})()") boolValue],@"moving focus into the explanation keeps the readable, scrollable dialog open");
 [host close];printf("PASS: %lu offline renderer and security assertions\n",(unsigned long)checks);
}return 0;}
